      loader.hidden=true;loader.setAttribute("aria-hidden","true");startButton.disabled=false;showView("duel");renderDuel();showBattleIntro({playerName:window.MythicOnline?.playerName?.()||"Você",playerIcon:window.MythicOnline?.playerIcon?.()||"default",playerRating:window.MythicOnline?.playerRating?.()||1000,enemyName:"Guardião da Arena",enemyIcon:"guardian",after:()=>{if(duel?.isTutorial)startTutorial();}});
