    const state={...duel.rulesState,round:duel.round,sharedZones:duel.sharedZones,eclipseReveal:duel.eclipseReveal,zoneOwners:duel.zoneOwners||{},zoneCards:duel.zoneCards||duel.rulesState?.zoneCards||{},silenceUntilRound:duel.silenceUntilRound||0,silenceTurns:duel.silenceTurns,silenceTeam:duel.silenceTeam,silenceStartedBy:duel.silenceStartedBy,endedTurns:duel.endedTurns,effectQueue:duel.effectQueue||[],pendingEffect:duel.pendingEffect,log:duel.log,endEffectsRound:duel.endEffectsRound,abilityPhase:duel.abilityPhase,visualEvents:duel.visualEvents||[],roundSummary:duel.roundSummary};state[mine]=duel.player;state[theirs]=duel.enemy;
